/**
 * DEF0777644: Test that missing mandatory inputs cause TypeScript errors.
 * Uses @ts-expect-error to verify type system correctly rejects invalid inputs.
 */
import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

// Test 1: Record Created trigger - missing mandatory 'table' should error
Flow(
    {
        $id: Now.ID['flow_trigger_missing_table'],
        name: 'DEF0777644: Missing Mandatory Table',
        description: 'Test that missing table input causes type error',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trig_missing_table'] },
        // @ts-expect-error Property 'table' is missing - mandatory field required
        { run_on_extended: 'false' }
    ),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_missing_table'] },
            {
                log_level: 'info',
                log_message: 'This should have type error for missing table',
            }
        )
    }
)

// Test 2: Daily trigger - missing mandatory 'time' should error
Flow(
    {
        $id: Now.ID['flow_trigger_missing_time'],
        name: 'DEF0777644: Missing Mandatory Time',
        description: 'Test that missing time input causes type error',
        runAs: 'system',
    },
    // @ts-expect-error Property 'time' is missing in type '{}' - mandatory field required
    wfa.trigger(trigger.scheduled.daily, { $id: Now.ID['trig_missing_time'] }, {}),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_missing_time'] },
            {
                log_level: 'info',
                log_message: 'This should have type error for missing time',
            }
        )
    }
)

// Test 3: SLA Task trigger - passing invalid inputs should error (no inputs defined)
Flow(
    {
        $id: Now.ID['flow_trigger_sla_invalid'],
        name: 'DEF0777644: SLA Invalid Inputs',
        description: 'Test that passing inputs to trigger with no inputs causes type error',
        runAs: 'system',
    },
    wfa.trigger(
        trigger.application.slaTask,
        { $id: Now.ID['trig_sla_invalid'] },
        {
            // @ts-expect-error Property 'invalid_field' does not exist - trigger has no inputs defined
            invalid_field: 'test',
        }
    ),
    () => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['log_sla_invalid'] },
            {
                log_level: 'info',
                log_message: 'This should have type error for invalid inputs',
            }
        )
    }
)
